using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;
public static class DiningHallLayout {
 static Bounds B(Transform t){var rs=t.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void Place(Transform t,Vector3 center,float yaw,bool floor=false){t.rotation=Quaternion.Euler(0,yaw,0);var b=B(t);if(floor)center.y=b.extents.y;t.position+=center-b.center;}
 public static string Run(){var path="Assets/Prefabs/Building/I_DinningHall.prefab";Directory.CreateDirectory("Temp/DiningHallBackup");if(!File.Exists("Temp/DiningHallBackup/I_DinningHall.prefab"))File.Copy(path,"Temp/DiningHallBackup/I_DinningHall.prefab");var root=PrefabUtility.LoadPrefabContents(path);try{var parent=root.transform.Find("Furnishings");var all=parent.Cast<Transform>().ToArray();Transform Find(string n)=>all.First(t=>t!=null&&t.name==n);
 foreach(var t in all.Where(t=>System.Text.RegularExpressions.Regex.IsMatch(t.name,@"^(Banquet Table|Dining Chair|Place Setting|Table Candelabrum|Serving Bowl) [34]( |$)")))UnityEngine.Object.DestroyImmediate(t.gameObject);
 for(int i=1;i<=2;i++){float x=i==1?-7.5f:7.5f;var table=Find("Banquet Table "+i);Place(table,new Vector3(x,0,0),0,true);float top=B(table).max.y;
 foreach(int side in new[]{-1,1})for(int seat=-1;seat<=1;seat++){var chair=Find("Dining Chair "+i+" "+side+" "+seat);Place(chair,new Vector3(x+side*4.05f,0,seat*3),side<0?90:270,true);var setting=Find("Place Setting "+i+" "+side+" "+seat);var b=B(setting);Place(setting,new Vector3(x+side*1.75f,top+.025f+b.extents.y,seat*3),side<0?90:270);}
 var candel=Find("Table Candelabrum "+i);Place(candel,new Vector3(x,top+.025f+B(candel).extents.y,0),0);var bowl=Find("Serving Bowl "+i);Place(bowl,new Vector3(x,top+.025f+B(bowl).extents.y,-2),0);
 }
 foreach(int n in new[]{-11,11}){var sideboard=Find("Serving Sideboard "+n);float x=n<0?-9:9;Place(sideboard,new Vector3(x,0,-13.5f),0,true);foreach(var tuple in new[]{("Sideboard Bowl "+n,-1.4f),("Sideboard Crockery "+n,1.4f)}){var prop=Find(tuple.Item1);float px=x+tuple.Item2,pz=-12.7f,top=0;foreach(var mf in sideboard.GetComponentsInChildren<MeshFilter>()){var col=mf.gameObject.AddComponent<MeshCollider>();col.sharedMesh=mf.sharedMesh;if(col.Raycast(new Ray(new Vector3(px,5,pz),Vector3.down),out var hit,5))top=Mathf.Max(top,hit.point.y);UnityEngine.Object.DestroyImmediate(col);}if(top<1)throw new Exception("Missing sideboard support");Place(prop,new Vector3(px,top+.025f+B(prop).extents.y,pz),0);}}
 var monster=root.transform.Find("MonsterPoint");if(monster!=null)monster.localPosition=new Vector3(0,0,-9);PrefabUtility.SaveAsPrefabAsset(root,path);return "Two six-seat banquet tables, paired settings, supported sideboard dishes, clear central and perimeter circulation";}finally{PrefabUtility.UnloadPrefabContents(root);}}
}

